import 'package:flutter/material.dart';
import '../services/api_service.dart';

class HistoryScreen extends StatefulWidget { const HistoryScreen({super.key}); @override State<HistoryScreen> createState()=>_HistoryScreenState(); }
class _HistoryScreenState extends State<HistoryScreen>{List<dynamic> rows=[];bool loading=true;@override void initState(){super.initState();load();}Future<void>load()async{try{final r=await ApiService.history();setState((){rows=r['data']??[];loading=false;});}catch(e){setState(()=>loading=false);if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Riwayat Absensi',style:TextStyle(fontWeight:FontWeight.w800))),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView.separated(padding:const EdgeInsets.all(16),itemCount:rows.length,separatorBuilder:(_,__)=>const SizedBox(height:9),itemBuilder:(_,i){final a=rows[i] as Map<String,dynamic>;return Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xFF0B1D31),borderRadius:BorderRadius.circular(16),border:Border.all(color:const Color(0xFF1B3D59))),child:Row(children:[Container(width:42,height:42,alignment:Alignment.center,decoration:BoxDecoration(shape:BoxShape.circle,color:const Color(0x1A6BD5A3)),child:const Icon(Icons.check,color:Color(0xFF6BD5A3))),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(a['tanggal']??'-',style:const TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:4),Text('${a['waktu']??'-'}  •  ${a['qr_location']?['nama_lokasi']??'-'}',style:const TextStyle(color:Color(0xFF819AAF),fontSize:11))])),Text((a['status']??'-').toString().toUpperCase(),style:const TextStyle(color:Color(0xFF6BD5A3),fontSize:10,fontWeight:FontWeight.w800))]);}));}
